<?php use App\Support\Ui; $days=[1=>'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']; ?>
<div class="page-heading"><div><span class="eyebrow">SCHEDULING POLICY</span><h1>Settings</h1><p>Control candidate notice, change cutoffs, and weekly operating hours.</p></div></div><?php if(isset($errors['form'])):?><div class="alert danger" role="alert"><?= $e($errors['form']) ?></div><?php endif; ?><?php if(isset($errors['hours'])):?><div class="alert danger" role="alert"><?= $e($errors['hours']) ?></div><?php endif; ?><form method="post" class="settings-layout" action="<?= $e($url('admin/settings')) ?>" data-submit><?= Ui::csrf() ?><section class="card settings-card"><div class="card-heading"><div><h2>Candidate timing rules</h2><p>Admins may override these time cutoffs.</p></div></div><div class="form-grid"><div class="field"><label for="advance_minutes">Minimum booking notice</label><input id="advance_minutes" type="number" min="0" max="10080" name="advance_minutes" value="<?= $e($settings['advance_booking_minutes']??60) ?>" required><span class="field-hint">Minutes before interview start.</span><?= Ui::error($errors,'advance_minutes') ?></div><div class="field"><label for="cutoff_minutes">Cancel/reschedule cutoff</label><input id="cutoff_minutes" type="number" min="0" max="10080" name="cutoff_minutes" value="<?= $e($settings['candidate_change_cutoff_minutes']??60) ?>" required><span class="field-hint">Minutes before interview start.</span><?= Ui::error($errors,'cutoff_minutes') ?></div></div></section><section class="card settings-card"><div class="card-heading"><div><h2>Weekly business hours</h2><p>Updates that conflict with future bookings are blocked.</p></div></div><div class="hours-list"><?php foreach($hours as $row):$day=(int)$row['weekday'];?><div class="hours-row"><strong><?= $e($days[$day]) ?></strong><label class="open-toggle"><input type="checkbox" name="open[<?= $day ?>]" value="1" <?= $row['is_open']?'checked':'' ?>> Open</label><div class="field"><label for="opens<?= $day ?>">Opens</label><input id="opens<?= $day ?>" type="time" name="opens[<?= $day ?>]" value="<?= $e(substr($row['opens_at'],0,5)) ?>" required></div><div class="field"><label for="closes<?= $day ?>">Closes</label><input id="closes<?= $day ?>" type="time" name="closes[<?= $day ?>]" value="<?= $e(substr($row['closes_at'],0,5)) ?>" required></div></div><?php endforeach;?></div></section><div class="settings-actions"><button class="button primary" type="submit">Save scheduling settings</button><p>Every change is recorded in the audit log.</p></div></form>
